import React,{useEffect,useState} from "react";
import {Plus} from "lucide-react";
import api from "../services/api";

export default function Procurement(){
  const [data,setData]=useState([]);
  const [open,setOpen]=useState(false);
  const [msg,setMsg]=useState("");
  const [form,setForm]=useState({
    memberId:"",commodity:"",quantityKg:"",grade:"A",pricePerKg:"",
    procurementDate:new Date().toISOString().slice(0,10)
  });

  const load=()=>api.get("/procurements").then(r=>setData(r.data)).catch(()=>{});
  useEffect(load,[]);

  const submit=async e=>{
    e.preventDefault();
    try{
      await api.post("/procurements",{
        ...form,memberId:Number(form.memberId),
        quantityKg:Number(form.quantityKg),pricePerKg:Number(form.pricePerKg)
      });
      setMsg("Procurement created successfully.");
      setOpen(false); load();
    }catch(e){setMsg(e.response?.data?.message||"Unable to create procurement.");}
  };

  return (
    <>
      <div className="page-head">
        <div><span className="eyebrow">FARMER TRANSACTIONS</span><h2>Procurement</h2><p>Record and review produce procurement.</p></div>
        <button className="primary" onClick={()=>setOpen(true)}><Plus size={17}/> New procurement</button>
      </div>
      {msg&&<div className="toast">{msg}</div>}
      <div className="panel"><table>
        <thead><tr><th>Member</th><th>Commodity</th><th>Quantity</th><th>Grade</th><th>Price/kg</th><th>Total</th><th>Payment</th></tr></thead>
        <tbody>{data.map(p=><tr key={p.id}><td>{p.member?.name||"-"}</td><td>{p.commodity}</td><td>{p.quantityKg} kg</td><td><span className="grade">{p.grade}</span></td><td>₹{p.pricePerKg}</td><td><b>₹{p.totalAmount}</b></td><td><span className="badge pending">{p.paymentStatus}</span></td></tr>)}</tbody>
      </table></div>

      {open&&<div className="modal-bg"><form className="modal" onSubmit={submit}>
        <div className="modal-head"><h3>New Procurement</h3><button type="button" onClick={()=>setOpen(false)}>×</button></div>
        <div className="form-grid">
          <label>Member ID<input required value={form.memberId} onChange={e=>setForm({...form,memberId:e.target.value})}/></label>
          <label>Commodity<input required value={form.commodity} onChange={e=>setForm({...form,commodity:e.target.value})}/></label>
          <label>Quantity (kg)<input type="number" required value={form.quantityKg} onChange={e=>setForm({...form,quantityKg:e.target.value})}/></label>
          <label>Grade<select value={form.grade} onChange={e=>setForm({...form,grade:e.target.value})}><option>A</option><option>B</option><option>C</option></select></label>
          <label>Price per kg<input type="number" required value={form.pricePerKg} onChange={e=>setForm({...form,pricePerKg:e.target.value})}/></label>
          <label>Date<input type="date" value={form.procurementDate} onChange={e=>setForm({...form,procurementDate:e.target.value})}/></label>
        </div>
        <button className="primary full">Create procurement</button>
      </form></div>}
    </>
  );
}
